test('glossary sends only terms present in the current fragment and a changed mapping invalidates checkpoints',async t=>{
 const glossary={'倾向评分匹配':'propensity score matching','书院':'traditional academy','形成性评价':'formative assessment'},f=await fixture(t,{glossary});
 const source={title:'研究标题',summary:'教育摘要',markdown:'# 研究标题\n\n倾向评分匹配用于研究。\n\n书院采用形成性评价。'};let calls=0;
 const fetcher=async(url,options)=>{
  calls++;const text=textFrom(options),prompt=JSON.parse(options.body).messages[1].content;
  const expected=Object.fromEntries(Object.entries(glossary).filter(([term])=>text.includes(term)));
  if(Object.keys(expected).length){const actual=JSON.parse(prompt.split('TERMINOLOGY DATA:\n')[1].split('\n')[0]);assert.deepEqual(actual,expected);}
  else assert(!prompt.includes('TERMINOLOGY DATA:'));
  for(const [term,english] of Object.entries(glossary))if(!text.includes(term))assert(!prompt.includes(english));
  return response(text);
 };
 const run=()=>translateHttpEdition(source,{root:f.root,plan},{configFile:f.configFile,timeoutMs:100000,fetcher});
 await run();assert.equal(calls,4);await run();assert.equal(calls,4);
 glossary['书院']='academy of classical learning';await writeFile(f.configFile,JSON.stringify({...f.config,glossary}));await run();assert.equal(calls,8);
});

